using SharpTS.Tests.Infrastructure;
using Xunit;

namespace SharpTS.Tests.SharedTests;

public sealed class PrimitivePrototypeDottedAssignmentTests
{
    public static IEnumerable<object[]> Cases()
    {
        yield return ["number-dot-compound", "const p:any=Number.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});console.log(p.probe+=2,p.probe);\n", "3 3\n"];
        yield return ["number-dot-increment", "const p:any=Number.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});console.log(++p.probe,p.probe);\n", "2 2\n"];
        yield return ["boolean-dot-compound", "const p:any=Boolean.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});console.log(p.probe+=2,p.probe);\n", "3 3\n"];
        yield return ["boolean-dot-increment", "const p:any=Boolean.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});console.log(++p.probe,p.probe);\n", "2 2\n"];
        yield return ["number-accessor-compound", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe+=rhs();console.log(result,stored,log.join(','),receiver);\n", "3 3 get,rhs,set3 true\n"];
        yield return ["number-accessor-postfix", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe++;console.log(result,stored,log.join(','),receiver);\n", "1 2 get,set2 true\n"];
        yield return ["number-logical-or", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=0;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe||=rhs();console.log(result,stored,log.join(','),receiver);\n", "2 2 get,rhs,set2 true\n"];
        yield return ["number-logical-and-short", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=0;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe&&=rhs();console.log(result,stored,log.join(','),receiver);\n", "0 0 get true\n"];
        yield return ["number-logical-nullish", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=null;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe??=rhs();console.log(result,stored,log.join(','),receiver);\n", "2 2 get,rhs,set2 true\n"];
        yield return ["number-strict-readonly", "'use strict';const p:any=Number.prototype;const log:string[]=[];Object.defineProperty(p,'probe',{value:1,writable:false,configurable:true});function rhs():any{log.push('rhs');return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "true 1 rhs\n"];
        yield return ["number-sloppy-readonly", "const p:any=Number.prototype;const log:string[]=[];Object.defineProperty(p,'probe',{value:1,writable:false,configurable:true});function rhs():any{log.push('rhs');return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "false 1 rhs\n"];
        yield return ["number-inherited-objectprototype-setter", "'use strict';const p:any=Number.prototype,base:any=Object.prototype;let stored=1,receiver=false;Object.defineProperty(base,'probe',{get(){return stored},set(v:any){receiver=this===p;stored=v}});console.log(p.probe+=2,stored,receiver,Object.prototype.hasOwnProperty.call(p,'probe'));\n", "3 3 true false\n"];
        yield return ["number-prevented-setter", "'use strict';const p:any=Number.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});Object.preventExtensions(p);console.log(p.probe+=2,stored,log.join(','),receiver);\n", "3 3 get,set3 true\n"];
        yield return ["number-rhs-redefines-readonly", "'use strict';const p:any=Number.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});const log:string[]=[];function rhs():any{log.push('rhs');Object.defineProperty(p,'probe',{value:9,writable:false});return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "true 9 rhs\n"];
        yield return ["boolean-accessor-compound", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe+=rhs();console.log(result,stored,log.join(','),receiver);\n", "3 3 get,rhs,set3 true\n"];
        yield return ["boolean-accessor-postfix", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe++;console.log(result,stored,log.join(','),receiver);\n", "1 2 get,set2 true\n"];
        yield return ["boolean-logical-or", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=0;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe||=rhs();console.log(result,stored,log.join(','),receiver);\n", "2 2 get,rhs,set2 true\n"];
        yield return ["boolean-logical-and-short", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=0;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe&&=rhs();console.log(result,stored,log.join(','),receiver);\n", "0 0 get true\n"];
        yield return ["boolean-logical-nullish", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=null;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});function rhs():any{log.push('rhs');return 2}const result=p.probe??=rhs();console.log(result,stored,log.join(','),receiver);\n", "2 2 get,rhs,set2 true\n"];
        yield return ["boolean-strict-readonly", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];Object.defineProperty(p,'probe',{value:1,writable:false,configurable:true});function rhs():any{log.push('rhs');return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "true 1 rhs\n"];
        yield return ["boolean-sloppy-readonly", "const p:any=Boolean.prototype;const log:string[]=[];Object.defineProperty(p,'probe',{value:1,writable:false,configurable:true});function rhs():any{log.push('rhs');return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "false 1 rhs\n"];
        yield return ["boolean-inherited-objectprototype-setter", "'use strict';const p:any=Boolean.prototype,base:any=Object.prototype;let stored=1,receiver=false;Object.defineProperty(base,'probe',{get(){return stored},set(v:any){receiver=this===p;stored=v}});console.log(p.probe+=2,stored,receiver,Object.prototype.hasOwnProperty.call(p,'probe'));\n", "3 3 true false\n"];
        yield return ["boolean-prevented-setter", "'use strict';const p:any=Boolean.prototype;const log:string[]=[];let stored:any=1;let receiver=true;Object.defineProperty(p,'probe',{configurable:true,get(){log.push('get');receiver=receiver&&this===p;return stored},set(v:any){log.push('set'+String(v));receiver=receiver&&this===p;stored=v}});Object.preventExtensions(p);console.log(p.probe+=2,stored,log.join(','),receiver);\n", "3 3 get,set3 true\n"];
        yield return ["boolean-rhs-redefines-readonly", "'use strict';const p:any=Boolean.prototype;Object.defineProperty(p,'probe',{value:1,writable:true,configurable:true});const log:string[]=[];function rhs():any{log.push('rhs');Object.defineProperty(p,'probe',{value:9,writable:false});return 2}let caught=false;try{p.probe+=rhs()}catch(e){caught=e instanceof TypeError}console.log(caught,p.probe,log.join(','));\n", "true 9 rhs\n"];
    }

    public static IEnumerable<object[]> Modes() => Cases().SelectMany(row =>
        new[] { ExecutionMode.Interpreted, ExecutionMode.Compiled }.Select(mode =>
            new object[] { row[0], row[1], row[2], mode }));

    [Theory, MemberData(nameof(Modes))]
    public void DottedUpdatesUseCurrentDescriptors(string name, string source, string expected, ExecutionMode mode)
    {
        Assert.NotEmpty(name);
        if (mode == ExecutionMode.Compiled)
        {
            var (errors, output) = TestHarness.CompileVerifyAndRun(source);
            Assert.Empty(errors);
            Assert.Equal(expected, output);
        }
        else Assert.Equal(expected, TestHarness.Run(source, mode));
    }
}
